"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["31072"],{13184(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>o,contentTitle:()=>p,toc:()=>h,assets:()=>d});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-participant-search","title":"Participant search","description":"Reads a participant\'s full registry record by participant_code, including roles, status, encryption_cert and endpoint_url.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-participant-search.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-participant-search","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-participant-search","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Participant search","sidebar_label":"Participant search","sidebar_class_name":"api-method api-method--post","description":"Reads a participant\'s full registry record by participant_code, including roles, status, encryption_cert and endpoint_url.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Participant certificate and bridge update (v2)","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-update"},"next":{"title":"Participant details (v2 search)","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-participant-details"}}'),r=a(62540),n=a(43023),s=a(70862),c=JSON.parse('{"id":"registry_participant_search","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/participant/search","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Participant search","description":"Reads a participant\'s full registry record by participant_code, including roles, status, encryption_cert and endpoint_url.\\n\\n### Business purpose\\n\\nBefore addressing a transaction to a counterparty, an integrator needs to know that the participant exists, is active, holds the expected role and publishes an encryption certificate and callback endpoint. The registry is the phone book of NHCX, and this call is the direct lookup by code. Providers use it to inspect a payer they have selected; payers use it to confirm the sender of an inbound request; everyone uses it to verify their own record after an update.\\n\\n### When to use\\n\\nCall it once a participant_code is known, typically after /fetch/participants/list has produced candidates, or before building the first JWE for a new recipient. It is also the natural post-update check after /participant/update, /v2/participant/update or /v2/update/cert. It is a synchronous JSON registry call with no workflow or x-hcx-status codes. /participant/details takes the same body and returns the same response; the OpenAPI identifies it only as the v2 variant.\\n\\n### Preconditions\\n\\n- A Bearer token from /get/session in bearer_auth with the Bearer prefix; Accept and Content-Type: application/json.\\n- The target\'s participant_code in xxxxx@hcx (or @sbx) form, exactly the value later placed in x-hcx-recipient_code.\\n- Sandbox base https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search; production under https://apis.abdm.gov.in/pmjay/hcx.\\n\\n### Postconditions\\n\\nHTTP 200 with ParticipantSearchResponse: timestamp (Unix timestamp when the request is sent) and participants, an array of full participant records with participant_code, linked_registry_codes, participant_name, scheme_code, roles, address, primaryEmail, additionalEmail, phone, primaryMobile, additionalMobile, status, signing_cert_path, encryption_cert, endpoint_url and payment_details. No state changes and no callback. An unknown code returns 404 with the ErrorResponse envelope; 400 and 500 are the other documented outcomes.\\n\\n### Common mistakes\\n\\n- Passing participantid or participantcode instead of the snake_case participant_code this body requires.\\n- Assuming a record in the registry means the participant can transact; status must be Active, and NHCX-1003 (receiver not registered) still results if the code is wrong or inactive.\\n- Reading encryption_cert as the certificate content when it is documented as a URI or file path to the certificate; use /fetch/certs to obtain the key material.\\n- Forgetting the Accept header, which causes rejection before business logic.\\n- Sending an expired token and misreading the flat 401.\\n\\n### Best practices\\n\\n- Cache the record for the session and re-read it when a transport error (NHCX-1001) or decrypt failure (PAYR-1001/PAYR-1002) suggests stale routing or key data.\\n- Check roles and status before selecting the counterparty for x-hcx-recipient_code.\\n- Call it against your own code after every registry update to confirm the change is live.\\n- Never log payment_details from the response.\\n- Treat the participants array as possibly empty and handle 404 gracefully.\\n\\n### Related scenario\\n\\nA hospital\'s TPA desk has selected a payer code from /fetch/participants/list for a PMJAY patient. Before submitting anything the integration calls /participant/search with that participant_code and receives the payer\'s record: roles include payer, status is Active, scheme_code matches, and endpoint_url and encryption_cert are populated. The engine stores the code as the payerId that will become x-hcx-recipient_code, calls /fetch/certs to obtain the actual certificate, and then encrypts and sends /v1/coverageeligibility/check.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"participant_code","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"participant_code":"1518@hcx"},"responses":[{"status":"200","description":"HTTP 200 with ParticipantSearchResponse: timestamp (Unix timestamp when the request is sent) and participants, an array of full participant records with participant_code, linked_registry_codes, participant_name, scheme_code, roles, address, primaryEmail, additionalEmail, phone, primaryMobile, additionalMobile, status, signing_cert_path, encryption_cert, endpoint_url and payment_details.","example":{"timestamp":1716204567358,"participants":[{"participant_code":"1518@hcx","participant_name":"Demo Insurance Company","linked_registry_codes":["125@payer"],"scheme_code":"default","roles":["payer"],"status":["Active"],"primaryEmail":"claims@demoinsurer.example.in","primaryMobile":"9800000001","encryption_cert":"https://registry.example.in/certs/1518.pem","endpoint_url":"https://nhcx.demoinsurer.example.in"}]}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/search \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participant_code\\": \\"1518@hcx\\"\\n}\'"}');let o={title:"Participant search",sidebar_label:"Participant search",sidebar_class_name:"api-method api-method--post",description:"Reads a participant's full registry record by participant_code, including roles, status, encryption_cert and endpoint_url.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},p,d={},h=[];function l(e){return(0,r.jsx)(s.A,{operation:c})}function u(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}}}]);